function longest(onTime, maxLate) {
  let left = 0, late = 0, best = 0;
  for (let right = 0; right < onTime.length; right++) {
    if (!onTime[right]) late++;
    while (late > maxLate) {
      if (!onTime[left]) late--;
      left++;
    }
    best = Math.max(best, right - left + 1);
  }
  return best;
}
const T = true, F = false;
console.log(longest([T, F, T, T, F, T, T, T], 0), longest([T, F, T, T, F, T, T, T], 1));

function longest(items) {
  const last = new Map();
  let left = 0, best = 0;
  for (let right = 0; right < items.length; right++) {
    const prev = last.get(items[right]);
    if (prev !== undefined && prev >= left) left = prev + 1;
    last.set(items[right], right);
    best = Math.max(best, right - left + 1);
  }
  return best;
}
