function maxPerWindow(values, k) {
  const q = [];
  let head = 0;
  const out = [];
  for (let right = 0; right < values.length; right++) {
    while (q.length > head && values[q[q.length - 1]] <= values[right]) q.pop();
    q.push(right);
    if (q[head] <= right - k) head++;
    if (right >= k - 1) out.push(values[q[head]]);
  }
  return out;
}
