const daily = [50, 20, 70, 10, 90, 30, 60, 80, 40, 100, 10];

function bestWeek(values, k) {
  if (values.length < k) return null;
  let total = 0;
  for (let i = 0; i < k; i++) total += values[i];
  let best = total;
  for (let right = k; right < values.length; right++) {
    total += values[right] - values[right - k];
    if (total > best) best = total;
  }
  return best;
}

console.log(bestWeek(daily, 7), bestWeek([1, 2, 3], 7));

