const daily = [2, 1, 5, 2, 3, 2];

function shortestRun(values, target) {
  let left = 0;
  let total = 0;
  let best = Infinity;
  for (let right = 0; right < values.length; right++) {
    total += values[right];
    while (total >= target) {
      best = Math.min(best, right - left + 1);
      total -= values[left];
      left++;
    }
  }
  return best === Infinity ? 0 : best;
}

console.log(shortestRun(daily, 7), shortestRun(daily, 100));

