function movingAverage(values, k) {
  const out = [];
  let total = 0;
  for (let i = 0; i < values.length; i++) {
    total += values[i];
    if (i >= k) total -= values[i - k];
    if (i >= k - 1) out.push(Math.round(total / k));
  }
  return out;
}

console.log(movingAverage(daily, 3).join(" "));

